SELECT p.id AS position_id, w.id, w.signal_id, w.position_analysis_id, w.side, w.quantity, w.price_usdt, w.decision_price_usdt, w.execution_price_observed_at, w.gross_amount_usdt, w.fee_usdt, w.net_amount_usdt, w.realized_pnl_usdt, w.execution_type, w.execution_reason, w.status, w.executed_at, LEFT(w.notes,300) AS notes, LEFT(w.execution_message,600) AS execution_message FROM paper_position p JOIN wallet_trade w ON w.symbol = p.symbol AND w.executed_at BETWEEN p.opened_at - INTERVAL 30 SECOND AND p.closed_at + INTERVAL 30 SECOND WHERE p.id IN (104,101,96,91,82,78) ORDER BY p.id, w.executed_at